(()=>{
const $=s=>document.querySelector(s);const put=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};const get=k=>{try{return localStorage.getItem(k)}catch{return null}};
let toastTimer;window.gtToast=text=>{let el=$('#gtToast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500)};
$('#quickToggle').onclick=()=>{const open=$('#quickActions').hidden;$('#quickActions').hidden=!open;$('#quickToggle').setAttribute('aria-expanded',String(open))};$('#navBack').onclick=()=>{if(history.length>1)history.back();else window.gtToast('这是当前标签的起点，可用主页或目录继续阅读。')};$('#navForward').onclick=()=>history.forward();$('#navTop').onclick=()=>scrollTo({top:0,behavior:scrollY>innerHeight*1.8||document.body.classList.contains('motion-off')?'instant':'smooth'});$('#navBottom').onclick=()=>moveTo($('#pageEnd'));$('#navToc').onclick=()=>{$('#toc').hidden=false;$('#tocToggle').setAttribute('aria-expanded','true');$('#tocToggle').focus()};$('#navRead').onclick=()=>{$('#readerControls').hidden=!$('#readerControls').hidden};$('#closeRead').onclick=()=>$('#readerControls').hidden=true;
function applyControls(){const size=get('gt-text-size');if(size)document.body.style.setProperty('--read-size',Math.min(23,Math.max(15,Number(size)))+'px');$('#textSize').value=size|| (innerWidth<700?16:17);$('#sizeLabel').textContent=$('#textSize').value+' px';const motion=get('gt-motion')==='off'||(get('gt-motion')===null&&matchMedia('(prefers-reduced-motion: reduce)').matches);document.body.classList.toggle('motion-off',motion);document.documentElement.classList.toggle('motion-off',motion);$('#gentleMotion').checked=!motion;const focus=get('gt-focus')==='yes';document.body.classList.toggle('reading-mode',focus);$('#focusRead').checked=focus;const marks=get('gt-editor-marks')!=='off';document.body.classList.toggle('marks-off',!marks);$('#editorMarks').checked=marks;$('#marksToggle').textContent=marks?'隐藏编辑重点':'显示编辑重点'}
$('#textSize').oninput=e=>{put('gt-text-size',e.target.value);document.body.style.setProperty('--read-size',e.target.value+'px');$('#sizeLabel').textContent=e.target.value+' px'};$('#gentleMotion').onchange=e=>{put('gt-motion',e.target.checked?'on':'off');applyControls()};$('#focusRead').onchange=e=>{put('gt-focus',e.target.checked?'yes':'no');applyControls()};$('#editorMarks').onchange=e=>{put('gt-editor-marks',e.target.checked?'on':'off');applyControls()};$('#marksToggle').onclick=()=>{put('gt-editor-marks',document.body.classList.contains('marks-off')?'on':'off');applyControls()};applyControls();
const marked=new WeakSet();const groups=[['core','与基督联合|三一神|因信称义|唯一中保|唯一安慰|一次完全|基督已经满足公义'],['order','信心只是领受的工具|信心不是功德|称义|成圣|重生'],['covenant','恩典之约|圣约|神的应许|约的应许'],['guard','不可混同|不可分离|不能互换|不是自动得救|不是罪的作者|不等于|不以预见信心为条件']];const re=new RegExp(groups.map(x=>`(${x[1]})`).join('|'),'g');
function editorial(){document.querySelectorAll('.essay p,.card p,.question p,.detail>p,.dort-article>p,.errors li p').forEach(p=>{if(marked.has(p)||p.classList.contains('ref')||p.closest('#sources,#memory'))return;marked.add(p);let used=0;const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('a,strong,mark,button,.pill')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{if(used>=2)return;const text=n.textContent;re.lastIndex=0;let m,last=0,frag=document.createDocumentFragment(),changed=false;while((m=re.exec(text))&&used<2){frag.append(document.createTextNode(text.slice(last,m.index)));const tag=document.createElement('span');let ix=m.slice(1).findIndex(Boolean);tag.className='key-'+groups[ix][0];tag.textContent=m[0];frag.append(tag);last=m.index+m[0].length;used++;changed=true}if(changed){frag.append(document.createTextNode(text.slice(last)));n.replaceWith(frag)}})});document.dispatchEvent(new Event('gt:marked'))}
function scheduleEditorial(){if('requestIdleCallback'in window)requestIdleCallback(editorial,{timeout:1200});else setTimeout(editorial,60)}document.addEventListener('gt:ready',scheduleEditorial);if(document.querySelector('.question'))scheduleEditorial();
const sections=[...document.querySelectorAll('main>section')];const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible[0]){let s=visible[0].target;$('#navContext').textContent=s.querySelector('h2,h1')?.textContent.replace(/\s+/g,' ').slice(0,28)||'研读导航'}},{rootMargin:'-80px 0px -55% 0px'});sections.forEach(s=>observer.observe(s));
const animatedObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('offscreen',!e.isIntersecting)),{rootMargin:'60px'});document.querySelectorAll('.hero,.geo-stage').forEach(e=>animatedObserver.observe(e));
function moveTo(target){if(!target)return;let d=target.closest('details');while(d){d.open=true;d=d.parentElement.closest('details')}const distance=Math.abs(target.getBoundingClientRect().top);target.scrollIntoView({behavior:distance>innerHeight*1.8||document.body.classList.contains('motion-off')?'instant':'smooth',block:'start'})}document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||e.defaultPrevented||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const target=document.getElementById(a.hash.slice(1));if(!target)return;e.preventDefault();if(location.hash!==a.hash)history.pushState(null,'',a.hash);moveTo(target)});function restoreHash(){if(location.hash)requestAnimationFrame(()=>{let target=document.getElementById(location.hash.slice(1));if(target){let d=target.closest('details');while(d){d.open=true;d=d.parentElement.closest('details')}target.scrollIntoView({behavior:'instant',block:'start'})}})}document.addEventListener('gt:ready',restoreHash);addEventListener('popstate',restoreHash);if(document.querySelector('.question'))restoreHash();
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#readerControls').hidden=true;$('#quickActions').hidden=true;$('#quickToggle').setAttribute('aria-expanded','false')}});
})();
